const telegramData = $('Extraer Datos Telegram').first().json;
const sessionRows = $('Buscar Sesion').all();
const citasRows = $('Leer Citas Existentes').all();

const chat_id = telegramData.chat_id;
const telegram_user = String(telegramData.telegram_user);
const username = telegramData.username || '';
let texto = (telegramData.texto || '').toString().trim();

const LIMITE_INACTIVIDAD_MS = 5 * 60 * 1000; // 5 minutos sin responder = sesion vencida

const sessionRowsValidas = sessionRows
  .filter(r => r.json && r.json.pantalla_actual !== undefined && r.json.pantalla_actual !== '')
  .sort((a, b) => new Date(b.json.timestamp_ultima_interaccion || 0) - new Date(a.json.timestamp_ultima_interaccion || 0));

const sessionMasReciente = sessionRowsValidas.length > 0 ? sessionRowsValidas[0].json : null;

let sesion_vencida = false;
if (sessionMasReciente && sessionMasReciente.timestamp_ultima_interaccion) {
  const ultimaInteraccion = new Date(sessionMasReciente.timestamp_ultima_interaccion);
  if (!isNaN(ultimaInteraccion.getTime()) && (Date.now() - ultimaInteraccion.getTime()) > LIMITE_INACTIVIDAD_MS) {
    sesion_vencida = true;
  }
}

// session_exists solo indica si hay una fila que reutilizar (Actualizar vs Crear).
// Si la sesion vencio, igual se reutiliza la misma fila pero con datos reiniciados,
// para no acumular filas en SESSIONS en cada expiracion.
const session_exists = sessionMasReciente !== null;
const sessionData = (sessionMasReciente && !sesion_vencida) ? sessionMasReciente : {};

const citasExistentes = citasRows
  .map(r => r.json)
  .filter(c => c && c.fecha);

let pantalla = sessionData.pantalla_actual || 'inicio';
let paso = parseInt(sessionData.paso_actual) || 0;
let datos = {};
try {
  datos = sessionData.datos_parciales ? JSON.parse(sessionData.datos_parciales) : {};
} catch (e) {
  datos = {};
}

const MENU_PRINCIPAL_TEXTO =
`Menu principal:
0. Ayuda
1. Agenda (citas)
2. Tareas
3. Recordatorios
4. Habitos
5. Listas
6. Reportes
7. Configuracion
8. Administrador`;

const MENU_AGENDA_TEXTO =
`1. Agendar una nueva cita
2. Consultar tu agenda
3. Reprogramar una cita
4. Cancelar una cita
5. Marcar una cita como completada
9. Volver al menu principal`;

function mensajeInvalido(opciones, pantallaNombre) {
  return `Ups, esa opcion no existe en este menu.

Por favor escribe uno de los numeros que ves en pantalla.

Estas en: ${pantallaNombre}
Opciones disponibles: ${opciones}`;
}

function validarFecha(str) {
  const regex = /^\d{4}-\d{2}-\d{2}$/;
  if (!regex.test(str)) return { valido: false, motivo: 'formato' };
  const partes = str.split('-').map(Number);
  const fechaIngresada = new Date(partes[0], partes[1] - 1, partes[2]);
  if (
    fechaIngresada.getFullYear() !== partes[0] ||
    (fechaIngresada.getMonth() + 1) !== partes[1] ||
    fechaIngresada.getDate() !== partes[2]
  ) {
    return { valido: false, motivo: 'formato' };
  }
  const hoy = new Date();
  hoy.setHours(0, 0, 0, 0);
  if (fechaIngresada < hoy) return { valido: false, motivo: 'pasado' };
  return { valido: true };
}

function validarHora(str) {
  const regex = /^([01]\d|2[0-3]):([0-5]\d)$/;
  return regex.test(str);
}

function generarIdCita() {
  const numero = citasExistentes.length + 1;
  return `CITA-${String(numero).padStart(3, '0')}`;
}

function hayDobleReserva(fecha, hora) {
  return citasExistentes.some(c =>
    c.fecha === fecha &&
    c.hora === hora &&
    c.estado !== 'cancelada'
  );
}

function hayDobleReservaExcluyendo(fecha, hora, idExcluir) {
  return citasExistentes.some(c =>
    c.fecha === fecha &&
    c.hora === hora &&
    c.estado !== 'cancelada' &&
    c.id_cita !== idExcluir
  );
}

function listarCitasAccionables() {
  return citasExistentes
    .filter(c => String(c.creado_por) === telegram_user && c.estado === 'pendiente')
    .sort((a, b) => (a.fecha + ' ' + a.hora).localeCompare(b.fecha + ' ' + b.hora));
}

function formatearListado(citas) {
  return citas
    .map(c => `${c.id_cita} | ${c.fecha} ${c.hora} - ${c.nombre} - ${c.motivo} (${c.canal})`)
    .join('\n');
}

function buscarCitaAccionable(id) {
  const idBuscado = (id || '').trim().toUpperCase();
  return citasExistentes.find(c =>
    c.id_cita === idBuscado &&
    String(c.creado_por) === telegram_user &&
    c.estado === 'pendiente'
  );
}

let respuesta = '';
let nueva_pantalla = pantalla;
let nuevo_paso = paso;
let guardar_cita = false;
let cita_data = null;
let reprogramar_cita = false;
let reprogramar_data = null;
let actualizar_estado_cita = false;
let estado_data = null;
let resultado = 'ok';
let pantalla_log = pantalla;


// --- Estado: inicio (primer contacto o desconocido) ---
if (pantalla === 'inicio' || !pantalla) {
  respuesta =
`Hola, soy AgendaBot

Estoy aqui para ayudarte a organizar tus citas, tareas y recordatorios
de forma sencilla y sin complicaciones.

Puedes escribirme en cualquier momento.
Para avanzar, solo tienes que escribir el numero de la opcion que quieras usar.

${MENU_PRINCIPAL_TEXTO}

Tip rapido: escribe solo el numero (por ejemplo: 1) y presiona enviar.

Si quieres empezar rapido, te recomiendo la opcion 1 (Agenda).`;
  nueva_pantalla = 'menu_principal';
  nuevo_paso = 0;
  datos = {};

// --- Estado: menu principal ---
} else if (pantalla === 'menu_principal') {
  if (texto === '0') {
    respuesta =
`Tip rapido: escribe solo el numero (por ejemplo: 1) y presiona enviar.

${MENU_PRINCIPAL_TEXTO}

Si quieres empezar rapido, te recomiendo la opcion 1 (Agenda).`;
    nueva_pantalla = 'menu_principal';
  } else if (texto === '1') {
    respuesta =
`Perfecto, vamos con tu agenda.

Que deseas hacer?

${MENU_AGENDA_TEXTO}`;
    nueva_pantalla = 'menu_agenda';
  } else if (texto === '2') {
    respuesta =
`Genial, hablemos de tus tareas.

Que deseas hacer?

1. Crear una nueva tarea
2. Consultar mis tareas
3. Cambiar estado de una tarea
9. Volver al menu principal`;
    nueva_pantalla = 'menu_tareas';
  } else if (texto === '3') {
    respuesta =
`Recordatorios

Que deseas hacer?

1. Ver mi recordatorio de hoy
9. Volver al menu principal`;
    nueva_pantalla = 'menu_recordatorios';
  } else if (texto === '4') {
    respuesta =
`Hablemos de tus habitos.

Que deseas hacer?

1. Crear un nuevo habito
2. Consultar mis habitos
3. Cambiar estado de un habito
9. Volver al menu principal`;
    nueva_pantalla = 'menu_habitos';
  } else if (texto === '5') {
    respuesta =
`Hablemos de tus listas.

Que deseas hacer?

1. Crear una nueva lista
2. Consultar mis listas
3. Agregar item a una lista
4. Marcar item como completado
9. Volver al menu principal`;
    nueva_pantalla = 'menu_listas';
  } else if (['6', '7', '8'].includes(texto)) {
    respuesta =
`Ups, esta opción todavia esta en construccion.
Volvamos al menu principal.
Opciones disponibles:
Agenda, Tareas, Recordatorios, Habitos, Listas.

En que te puedo ayudar hoy?

${MENU_PRINCIPAL_TEXTO}

Si quieres empezar rapido, te recomiendo la opcion 1 (Agenda).`;
    nueva_pantalla = 'menu_principal';
    resultado = 'no_implementado';
  } else {
    respuesta = mensajeInvalido('0 al 8', 'Menu principal');
    nueva_pantalla = 'menu_principal';
    resultado = 'invalido';
  }

// --- Estado: menu agenda ---
} else if (pantalla === 'menu_agenda') {
  if (texto === '1') {
    respuesta =
`Empecemos a crear tu cita.

Paso 1 de 6
Cual es la fecha de la cita?

Formato: YYYY-MM-DD
Ejemplo: 2025-12-20

9. Cancelar`;
    nueva_pantalla = 'wizard_cita';
    nuevo_paso = 1;
    datos = {};
  } else if (texto === '2') {
    const misCitas = citasExistentes
      .filter(c => String(c.creado_por) === telegram_user && c.estado !== 'cancelada')
      .sort((a, b) => (a.fecha + ' ' + a.hora).localeCompare(b.fecha + ' ' + b.hora));

    if (misCitas.length === 0) {
      respuesta =
`No tienes citas registradas por el momento.

Que deseas hacer?

${MENU_AGENDA_TEXTO}`;
      nueva_pantalla = 'menu_agenda';
    } else {
      const listado = misCitas.map((c, i) =>
        `${i + 1}. ${c.fecha} ${c.hora} - ${c.nombre} - ${c.motivo} (${c.canal}) - Estado: ${c.estado} - ID: ${c.id_cita}`
      ).join('\n');

      respuesta =
`Estas son tus citas registradas:

${listado}

Que deseas hacer ahora?
1. Volver a Agenda
2. Ir al menu principal`;
      nueva_pantalla = 'post_consulta';
      nuevo_paso = 0;
    }
  } else if (texto === '3') {
    const activas = listarCitasAccionables();
    if (activas.length === 0) {
      respuesta =
`No tienes citas pendientes para reprogramar.

Que deseas hacer?

${MENU_AGENDA_TEXTO}`;
      nueva_pantalla = 'menu_agenda';
    } else {
      respuesta =
`Estas son tus citas pendientes:

${formatearListado(activas)}

Escribe el ID de la cita que deseas reprogramar (ejemplo: CITA-001).

9. Cancelar`;
      nueva_pantalla = 'reprogramar_seleccion';
      nuevo_paso = 1;
      datos = {};
    }
  } else if (texto === '4') {
    const activas = listarCitasAccionables();
    if (activas.length === 0) {
      respuesta =
`No tienes citas pendientes para cancelar.

Que deseas hacer?

${MENU_AGENDA_TEXTO}`;
      nueva_pantalla = 'menu_agenda';
    } else {
      respuesta =
`Estas son tus citas pendientes:

${formatearListado(activas)}

Escribe el ID de la cita que deseas cancelar (ejemplo: CITA-001).

9. Cancelar`;
      nueva_pantalla = 'cancelar_seleccion';
      nuevo_paso = 1;
      datos = {};
    }
  } else if (texto === '5') {
    const activas = listarCitasAccionables();
    if (activas.length === 0) {
      respuesta =
`No tienes citas pendientes para marcar como completadas.

Que deseas hacer?

${MENU_AGENDA_TEXTO}`;
      nueva_pantalla = 'menu_agenda';
    } else {
      respuesta =
`Estas son tus citas pendientes:

${formatearListado(activas)}

Escribe el ID de la cita que deseas marcar como completada (ejemplo: CITA-001).

9. Cancelar`;
      nueva_pantalla = 'completar_seleccion';
      nuevo_paso = 1;
      datos = {};
    }
  } else if (texto === '9') {
    respuesta =
`En que te puedo ayudar hoy?

${MENU_PRINCIPAL_TEXTO}

Si quieres empezar rapido, te recomiendo la opcion 1 (Agenda).`;
    nueva_pantalla = 'menu_principal';
  } else {
    respuesta = mensajeInvalido('1 al 5, 9', 'Menu Agenda');
    nueva_pantalla = 'menu_agenda';
    resultado = 'invalido';
  }

// --- Estado: wizard de agendamiento (Articulo 10) ---
} else if (pantalla === 'wizard_cita') {
  pantalla_log = `wizard_cita_paso${paso}`;

  if (texto === '9' && paso >= 1 && paso <= 5) {
    respuesta =
`Cita cancelada. No se guardo ninguna informacion.

Que deseas hacer?

${MENU_AGENDA_TEXTO}`;
