  } else {
    respuesta =
`Ese formato de hora no es valido.

Cual sera la nueva hora?

Formato 24 horas (HH:MM)
Ejemplo: 14:30

9. Cancelar`;
    resultado = 'invalido';
  }

// --- Estado: reprogramar - confirmacion ---
} else if (pantalla === 'reprogramar_confirmacion') {
