function validarFecha(str) {
  const regex = /^\d{4}-\d{2}-\d{2}$/;
  if (!regex.test(str)) return { valido: false, motivo: 'formato' };
  const partes = str.split('-').map(Number);
  const fechaIngresada = new Date(partes[0], partes[1] - 1, partes[2]);
  if (
    fechaIngresada.getFullYear() !== partes[0] ||
    (fechaIngresada.getMonth() + 1) !== partes[1] ||
    fechaIngresada.getDate() !== partes[2]
  ) {
    return { valido: false, motivo: 'formato' };
  }
  const hoy = new Date();
  hoy.setHours(0, 0, 0, 0);
  if (fechaIngresada < hoy) return { valido: false, motivo: 'pasado' };
  return { valido: true };
}

function generarIdTarea() {
  const numero = tareasExistentes.length + 1;
  return `TAREA-${String(numero).padStart(3, '0')}`;
}

function listarTareasAccionables() {
  return tareasExistentes
    .filter(t => String(t.creado_por) === telegram_user && t.estado !== 'completada')
    .sort((a, b) => (a.fecha_objetivo || '').localeCompare(b.fecha_objetivo || ''));
}

function formatearListadoTareas(tareas) {
  return tareas
    .map(t => `${t.id_tarea} | ${t.prioridad} | ${t.fecha_objetivo} - ${t.titulo} - Estado: ${t.estado}`)
    .join('\n');
}

function buscarTareaAccionable(id) {
  const idBuscado = (id || '').trim().toUpperCase();
  return tareasExistentes.find(t =>
    t.id_tarea === idBuscado &&
    String(t.creado_por) === telegram_user &&
    t.estado !== 'completada'
  );
}

