function mensajeInvalido(opciones, pantallaNombre) {
  return `Ups, esa opcion no existe en este menu.

Por favor escribe uno de los numeros que ves en pantalla.

Estas en: ${pantallaNombre}
Opciones disponibles: ${opciones}`;
}

function generarIdLista() {
  const numero = listasExistentes.length + 1;
  return `LISTA-${String(numero).padStart(3, '0')}`;
}

function generarIdItem() {
  const numero = itemsExistentes.length + 1;
  return `ITEM-${String(numero).padStart(3, '0')}`;
}

function listarListasPropias() {
  return listasExistentes
    .filter(l => String(l.creado_por) === telegram_user)
    .sort((a, b) => a.nombre_lista.localeCompare(b.nombre_lista));
}

function itemsDeLista(id_lista) {
  return itemsExistentes.filter(i => i.id_lista === id_lista);
}

function formatearListadoListas(listas) {
  return listas
    .map(l => {
      const items = itemsDeLista(l.id_lista);
      if (items.length === 0) {
        return `${l.id_lista} | ${l.nombre_lista} (${l.tipo}) - sin items`;
      }
      const lineasItems = items
        .map(i => `   ${i.estado === 'completado' ? '[x]' : '[ ]'} ${i.item} (${i.id_item})`)
        .join('\n');
      return `${l.id_lista} | ${l.nombre_lista} (${l.tipo})\n${lineasItems}`;
    })
    .join('\n\n');
}

function formatearListadoSimple(listas) {
  return listas.map(l => `${l.id_lista} | ${l.nombre_lista} (${l.tipo})`).join('\n');
}

function buscarListaPropia(id) {
  const idBuscado = (id || '').trim().toUpperCase();
  return listasExistentes.find(l =>
    l.id_lista === idBuscado &&
    String(l.creado_por) === telegram_user
  );
}

function buscarItemPendienteEnLista(id_lista, id_item) {
  const idBuscado = (id_item || '').trim().toUpperCase();
  return itemsExistentes.find(i =>
    i.id_item === idBuscado &&
    i.id_lista === id_lista &&
    i.estado !== 'completado'
  );
}

function formatearItemsPendientes(id_lista) {
  return itemsExistentes
    .filter(i => i.id_lista === id_lista && i.estado !== 'completado')
    .map(i => `${i.id_item} | ${i.item}`)
    .join('\n');
}

